def row(city: str, year: int, group: str, metric: str, value, unit: str, source_key: str, **kwargs) -> dict:
    source = SOURCES[source_key]
    data = {
        "城市": city,
        "统计年份": str(year),
        "指标组": group,
        "指标": metric,
        "数值": value,
        "单位": unit,
        "同比增长_pct": kwargs.get("yoy"),
        "占比_pct": kwargs.get("share"),
        "前年差值": kwargs.get("diff"),
        "前年差单位": kwargs.get("diff_unit", ""),
        "DDS维度类目": kwargs.get("dds", "市场环境"),
        "备注": kwargs.get("note", ""),
        "来源标题": source["来源标题"],
        "数据来源": source["数据来源"],
        "来源URL": source["来源URL"],
        "发布日期": source["发布日期"],
        "入库日期": TODAY,
        "来源摘录位置": kwargs.get("loc", ""),
    }
    return data


