def _write_city_index(df: pd.DataFrame) -> None:
    rows = []
    for city, group in df.groupby("城市"):
        rows.append(
            {
                "城市": city,
                "官方年度指标数": len(group),
                "统计年份": "、".join(sorted(group["统计年份"].astype(str).unique())),
                "来源数": group["来源URL"].nunique(),
                "有parquet": "是",
            }
        )
    index_path = MACRO / "_重点城市_index.csv"
    pd.DataFrame(rows).sort_values("城市").to_csv(index_path, index=False, encoding="utf-8-sig")


def _upsert_sources(df: pd.DataFrame) -> None:
    path = VAULT / "_sources.csv"
    cols = ["数据层", "文件", "来源标题", "发布机构或来源", "来源URL", "发布日期", "信任等级", "记录数", "入库日期", "备注"]
    sources = pd.read_csv(path, dtype=str, keep_default_na=False, encoding="utf-8-sig") if path.exists() else pd.DataFrame(columns=cols)
    for col in cols:
        if col not in sources.columns:
            sources[col] = ""
    sources = sources[cols]
    file_key = "宏观数据/重点城市-官方年度指标.csv"
    sources = sources[sources["文件"] != file_key].copy()

    rows = []
    for title, group in df.groupby("来源标题"):
        first = group.iloc[0]
        rows.append(
            {
                "数据层": "宏观数据",
                "文件": file_key,
                "来源标题": title,
                "发布机构或来源": first["数据来源"],
                "来源URL": first["来源URL"],
                "发布日期": first["发布日期"],
                "信任等级": "L1",
                "记录数": str(len(group)),
                "入库日期": TODAY,
                "备注": "官方统计公报/经济运行正文/统计年鉴表手工采录长表；每行保留来源摘录位置。",
            }
        )
    sources = pd.concat([sources, pd.DataFrame(rows)], ignore_index=True)
    sources.to_csv(path, index=False, encoding="utf-8-sig")
    sources.to_parquet(VAULT / "_sources.parquet", index=False)


def _upsert_root_manifest(df: pd.DataFrame) -> None:
    path = VAULT / "_manifest.csv"
    manifest = pd.read_csv(path, dtype=str, keep_default_na=False, encoding="utf-8-sig")
    target_path = "宏观数据\\重点城市-官方年度指标.csv"
    manifest = manifest[manifest["path"] != target_path].copy()
    years = "、".join(sorted(df["统计年份"].astype(str).unique()))
    cities = "/".join(sorted(df["城市"].astype(str).unique()))
    row_data = {
        "year": years,
        "city": cities,
        "dtype": "官方年度指标",
        "path": target_path,
        "rows": str(len(df)),
        "usable_price_rows": "",
        "usable_price_rate": "",
        "geo_valid_rate": "",
        "source": "official_statistical_communique",
        "trust": "L1",
        "is_synthetic": "False",
    }
    manifest = pd.concat([manifest, pd.DataFrame([row_data])], ignore_index=True)
    manifest.to_csv(path, index=False, encoding="utf-8-sig")
    manifest.to_parquet(VAULT / "_manifest.parquet", index=False)
    (VAULT / "_manifest.json").write_text(
        json.dumps(manifest.to_dict(orient="records"), ensure_ascii=False, indent=2),
        encoding="utf-8",
    )


def _write_manifest(df: pd.DataFrame) -> None:
    manifest_path = MACRO / "_manifest.md"
    existing = manifest_path.read_text(encoding="utf-8") if manifest_path.exists() else "# 宏观数据层 Manifest\n"
    existing = existing.replace(
        "- 仅采录网页正文中明确给出的数字，不对图片表或不可下载附件做推断。",
        "- 采录官方网页正文、PDF附件和统计年鉴表中明确给出的数字；图片表仅在官方年鉴页可追溯且经视觉/OCR复核后入库。",
    )
    years = "、".join(sorted(df["统计年份"].astype(str).unique()))
    cities = "/".join(sorted(df["城市"].astype(str).unique()))
    table_line = (
        "| `重点城市-官方年度指标.csv/.parquet` | "
        f"{len(df)} | {years} | {cities}统计局或政府门户统计公报/经济运行正文 |"
    )
    lines = existing.splitlines()
    replaced = False
    for idx, line in enumerate(lines):
        if line.startswith("| `重点城市-官方年度指标.csv/.parquet` |"):
            lines[idx] = table_line
            replaced = True
            break
    existing = "\n".join(lines)
    if not replaced:
        existing = existing.replace(
            "| `武汉-经济运行快报指标.csv/.parquet` | 83 | 2025全年、2025上半年、2026Q1 | 武汉市统计局新闻发布会经济运行正文 |",
            "| `武汉-经济运行快报指标.csv/.parquet` | 83 | 2025全年、2025上半年、2026Q1 | 武汉市统计局新闻发布会经济运行正文 |\n" + table_line,
        )
    if "重点城市官方年度指标层" not in existing:
        existing = existing.replace(
            "- 采录官方网页正文、PDF附件和统计年鉴表中明确给出的数字；图片表仅在官方年鉴页可追溯且经视觉/OCR复核后入库。",
            "- 采录官方网页正文、PDF附件和统计年鉴表中明确给出的数字；图片表仅在官方年鉴页可追溯且经视觉/OCR复核后入库。\n- 重点城市官方年度指标层为跨城长表，优先采录 GDP、人口、投资、房地产、轨道交通、居民收入等投拓相关指标。",
        )
    manifest_path.write_text(existing.rstrip() + "\n", encoding="utf-8")


def build() -> pd.DataFrame:
    MACRO.mkdir(parents=True, exist_ok=True)
    df = pd.DataFrame(RECORDS, columns=COLS)
    csv_path = MACRO / "重点城市-官方年度指标.csv"
    parquet_path = MACRO / "重点城市-官方年度指标.parquet"
    df.to_csv(csv_path, index=False, encoding="utf-8-sig")
    df.to_parquet(parquet_path, index=False)
    _write_city_index(df)
    _upsert_sources(df)
    _upsert_root_manifest(df)
    _write_manifest(df)
    return df


def main() -> None:
    df = build()
    counts = Counter(df["城市"])
    print(f"wrote {len(df)} rows to {MACRO}")
    for city in sorted(counts):
        print(f"{city}: {counts[city]}")


if __name__ == "__main__":
    main()


